@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@500;700&family=Outfit:wght@400;600;700;800;900&display=swap');
:root{--ink:#221c2d;--cream:#fff8e9;--orange:#ff713d;--teal:#56d6c6}

*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#efaa62;color:var(--ink);font-family:Outfit,system-ui,sans-serif;touch-action:none}
body{display:grid;place-items:center}
.game{position:relative;width:min(100vw,1280px);height:min(100dvh,800px);aspect-ratio:16/10;overflow:hidden;background:#f6ba70;box-shadow:0 20px 70px #482b3d55}
canvas{width:100%;height:100%;display:block}
.hud{position:absolute;inset:0;pointer-events:none}
.topbar{position:absolute;top:20px;left:24px;right:24px;display:flex;justify-content:space-between;align-items:flex-start}
.brand{font-size:13px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;background:var(--cream);padding:9px 13px;border:2px solid var(--ink);box-shadow:3px 3px 0 var(--ink);border-radius:8px}
.brand span{color:#e85e43}
.stats{display:flex;gap:8px}
.pill{min-width:88px;padding:8px 12px;text-align:center;border:2px solid var(--ink);border-radius:9px;background:var(--cream);box-shadow:3px 3px 0 var(--ink)}
.pill small{display:block;font:700 9px 'DM Mono',monospace;letter-spacing:.13em;color:#75677a}
.pill b{font:800 17px 'DM Mono',monospace}
.hearts{color:#ef5c55;letter-spacing:2px}
.distance-wrap{position:absolute;top:82px;left:24px;right:24px;display:flex;align-items:center;gap:10px;font:700 10px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.1em}
.track{height:8px;background:#fff2cf;border:1.5px solid var(--ink);border-radius:9px;overflow:hidden;flex:1}
.progress{height:100%;width:0;background:#f26446;transition:width .1s}
.bus-mark{font-size:18px}
.overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(180deg,#271e3133,#241b3955);pointer-events:auto}
.card{width:min(510px,calc(100% - 34px));text-align:center;padding:30px 34px 26px;background:var(--cream);border:3px solid var(--ink);border-radius:18px;box-shadow:8px 8px 0 var(--ink);position:relative}
.eyebrow{font:700 11px 'DM Mono',monospace;letter-spacing:.18em;color:#dc6045;text-transform:uppercase}
.card h1{font-size:clamp(38px,7vw,68px);line-height:.9;letter-spacing:-.06em;margin:12px 0 10px;font-weight:900}
.card h1 em{font-style:normal;color:#e85e43}
.card p{font-size:15px;line-height:1.5;color:#65596b;margin:10px auto 18px;max-width:380px}
.controls{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin:15px 0 20px}
.key{border:1.5px solid #b8aeb5;border-bottom-width:3px;border-radius:7px;padding:6px 9px;font:700 10px 'DM Mono',monospace;color:#473e50;background:white}
.key span{color:#e85e43}
.button{appearance:none;display:inline-block;border:2px solid var(--ink);background:#f36c46;color:#fff9e9;font:900 15px Outfit,sans-serif;letter-spacing:.06em;text-transform:uppercase;padding:13px 26px;border-radius:10px;box-shadow:4px 4px 0 var(--ink);cursor:pointer;pointer-events:auto}
.button:active{transform:translate(3px,3px);box-shadow:1px 1px 0 var(--ink)}
.foot{font:700 9px 'DM Mono',monospace;letter-spacing:.12em;color:#988b96;margin-top:18px}
.boss-tag{position:absolute;top:122px;left:50%;transform:translateX(-50%);font:800 11px 'DM Mono',monospace;letter-spacing:.12em;text-transform:uppercase;color:#fff2d5;background:#9d3e51;border:2px solid #321e34;padding:7px 12px;border-radius:7px;display:none}
.mobile-controls{position:absolute;left:0;right:0;bottom:max(15px,env(safe-area-inset-bottom));display:none;justify-content:space-between;padding:0 18px;pointer-events:none}
.pad{display:flex;gap:8px}
.touch{pointer-events:auto;width:54px;height:50px;border:2px solid var(--ink);border-radius:11px;background:#fff7e2dd;box-shadow:3px 3px 0 var(--ink);font-size:22px;font-weight:900;color:var(--ink);touch-action:none}
.touch:active{background:#ffcf79}
.toast{position:absolute;top:145px;left:50%;transform:translateX(-50%);font:700 12px 'DM Mono',monospace;color:#fff2d5;text-shadow:1px 2px #4c2842;opacity:0;transition:opacity .2s}
.hidden{display:none!important}
@media(max-width:650px){.game{width:100vw;height:100dvh;aspect-ratio:auto}
.topbar{top:max(12px,env(safe-area-inset-top));left:12px;right:12px}
.brand{font-size:10px;padding:7px 9px}
.stats{gap:5px}
.pill{min-width:64px;padding:6px 7px}
.pill b{font-size:14px}
.pill small{font-size:8px}
.distance-wrap{top:68px;left:13px;right:13px;font-size:8px}
.mobile-controls{display:flex}
.card{padding:25px 22px 21px}
.card p{font-size:14px}
.boss-tag{top:112px}

